use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::{BTreeMap,BTreeSet},fs,path::Path,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-vector-sign-default175";
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-default175";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
include!("metadata.rs");
fn main(){let r=Path::new(R);let d=Path::new(D);let declared=read(d.join("artifacts/review.json"));let mut archives=BTreeMap::new();
 for(name,key)in[("source","source_members"),("helpers","helper_members"),("receipts","receipt_members"),("proofs","proof_public_members")]{let p=d.join(format!("artifacts/{name}.json.gz"));let o=Command::new("gzip").args(["-d","-c"]).arg(&p).output().unwrap();assert!(o.status.success());let data:Value=serde_json::from_slice(&o.stdout).unwrap();let map=data.as_object().unwrap();assert_eq!(declared[key],map.len());let base=if name=="source"{r.join("source")}else{r.to_path_buf()};for(f,v)in map{assert!(!Path::new(f).is_absolute());assert!(!Path::new(f).components().any(|c|matches!(c,std::path::Component::ParentDir)));let b=v["bytes"].as_array().unwrap().iter().map(|x|u8::try_from(x.as_u64().unwrap()).unwrap()).collect::<Vec<_>>();assert_eq!(hash(&b),v["sha256"]);assert_eq!(b,fs::read(base.join(f)).unwrap());}archives.insert(name,json!({"members":map.len(),"member_hashes_and_bytes_match_originals":true,"sha256":hash(&fs::read(p).unwrap())}));}
 let a=read(r.join("analysis.json"));assert_eq!(a,read(d.join("artifacts/analysis.json")));assert_eq!(a["final_artifact_gate_passed"],true);assert_eq!(a["original_full_performance_gate_passed"],false);assert_eq!(a["independent_proof_count"],27264);assert_eq!(a["new_independent_exports"],972);assert_eq!(a["SDK_requests"],55788);assert!(a["failed_checks"].as_array().unwrap().is_empty());
 let mut profiles=serde_json::Map::new();for(n,p)in a["profiles"].as_object().unwrap(){let j=read(r.join("jobs.json"));let job=j.as_array().unwrap().iter().find(|j|j["name"]==*n).unwrap();let attrs=fs::read_to_string(r.join(format!("runs/events-{n}/stdout.log"))).unwrap();for needle in["cycles:u","16000000","CPU","TIME","PERIOD"]{assert!(attrs.contains(needle));}assert!(!attrs.contains("freq: 1"));assert_eq!(read(r.join(format!("runs/loss-{n}/stdout.log")))["zero_lost"],true);let meta=fs::read_to_string(r.join(format!("runs/metadata-{n}/stdout.log"))).unwrap();let(pid,tids)=profile_owners(&meta,job["binary"].as_str().unwrap());let decoded=fs::read_to_string(r.join(format!("runs/decode-{n}/stdout.log"))).unwrap();let(mut count,mut total,mut unknown)=(0u64,0u64,0u64);for line in decoded.lines().map(str::trim).filter(|l|!l.is_empty()&&!l.starts_with('#')){let f=line.split_whitespace().collect::<Vec<_>>();let(pp,tt)=f[0].split_once('/').unwrap();assert_eq!(pp.parse::<u32>().unwrap(),pid);assert!(tids.contains(&tt.parse::<u32>().unwrap()));let cpu=f[1].trim_matches(['[',']']).parse::<u64>().unwrap();assert!(cpu<job["case"]["workers"].as_u64().unwrap());let period=f[3].parse::<u64>().unwrap();assert_eq!(period,16000000);count+=1;total+=period;if f[5]=="[unknown]"{unknown+=period;}}assert_eq!(p["samples"],count);assert_eq!(p["period"],total);assert!(count>=1000);let share=unknown as f64/total as f64;assert!((share-p["unknown_period_share"].as_f64().unwrap()).abs()<1e-12);assert!(share<=0.05);profiles.insert(n.clone(),json!({"samples":count,"period":total,"unknown_share":share,"PID_TID_CPU_MMAP_ownership":true,"fixed_period_and_zero_loss":true}));}
 assert_eq!(profiles.len(),6);let m=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json");let mut changed=0;for(f,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(&fs::read(Path::new("/home/ubuntu/src/zk-tools/zopro").join(f)).unwrap()),h.as_str().unwrap());if hash(&fs::read(r.join("source").join(f)).unwrap())!=h.as_str().unwrap(){changed+=1;}}assert_eq!(changed,3);assert_eq!(read(r.join("final-source-review.json"))["passed"],true);
 assert_eq!(fs::read(d.join("accepted-rows.json")).unwrap(),fs::read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-sdk175/accepted-rows.json").unwrap());let mut tail=fs::read_to_string(d.join("README.md")).unwrap();let mut links=0;while let Some(i)=tail.find("]("){tail=tail[i+2..].to_string();let Some(j)=tail.find(')')else{break};let target=tail[..j].split('#').next().unwrap();if !target.is_empty()&&!target.starts_with("http"){assert!(d.join(target).exists(),"{target}");links+=1;}tail=tail[j+1..].to_string();}
 fs::write(d.join("artifacts/post-publication-review.json"),serde_json::to_vec_pretty(&json!({"passed":true,"archives":archives,"profiles_independently_recomputed":profiles,"production175_unchanged":true,"changed_snapshot_parents":3,"accepted_local_AWS_rows_exact":true,"verified_ledger":27264,"new_exports":972,"SDK_requests":55788,"readme_links_checked":links,"performance_test_or_verifier_reruns":0,"original_full_gate":false,"final_artifact_gate":true,"adopted":false,"goal_achieved":false})).unwrap()).unwrap();println!("All archive bytes/hashes, six profile ownership/period/loss/sample checks, production175, accepted rows and {links} links PASS; ledger27264; no reruns");
}
